function salgArcChoices(){
  const F=G.f,c=[];
  if(!F.yArcsSalg2)c.push({t:'왜 먹을 게 없어?',go:salgFoodArc});
  if(F.yArcsSalg2&&F.dadDone&&!F.yArcsSalg3)c.push({t:'우리 아빠였어. 고마워.',go:salgThanksArc});
  c.push({t:'길을 나선다',go:null});return c;
}
