/* ---------- 아빠: 몸짓 읽기 (틀려도 아빠가 다시 해 보인다) ---------- */
const GESTURES=[
  {pose:'mouth',reply:'nod',act:'(아빠가 내 눈을 보며 제 입을 짚는다.\n그러고는 천천히 고개를 젓는다.)',
   opts:[['말이… 안 나와?',1],['어디 아파?',0],['나한테 조용히 하라고?',0]],after:'(아빠가 크게 끄덕이며 내 어깨를 살며시 두드린다.)'},
  {pose:'cradle',reply:'heart',act:'(아빠가 나를 가리킨다. 아기를 안듯 두 팔을 모아\n살살 흔들더니, 가슴에 손을 얹는다.)',
   opts:[['나 안아 주려고?',0],['내가… 아기였을 때?',1],['추워?',0]],after:'(아빠의 눈이 젖는다. 작게 끄덕이며\n가슴에 얹었던 손을 내 손 위에 포갠다.)'},
  {pose:'paper',reply:'offer',act:'(아빠가 품에서 낡은 종이 한 장을 꺼낸다.\n내가 글씨를 볼 수 있게 돌려 두 손으로 내민다.)',
   opts:[['…나 주려고?',1],['이거, 뭐랑 바꾸자고?',0]],after:'(아빠가 눈웃음을 짓는다. 내 손을 펴 종이를 얹고,\n손끝을 가만히 감싸 준다.)'},
];
function dadPose(act){Rg.dadPose={act,tick:0,owner:G};}
/* 대화 중에도 도는 ambient에서 초상을 다시 그린다. 판정 시간제한은 없다. */
Rg.stepDadPose=()=>{
  const p=Rg.dadPose;if(!p)return;if(p.owner!==G){Rg.dadPose=null;return;}p.tick++;
  if(p.tick%6===0&&!$('dlg').hidden&&$('dlgWho').textContent==='아빠'){
    const face=$('dlgFace');face.replaceChildren(portrait('아빠'));
  }
};
const RETRIES=['(아빠가 살며시 고개를 젓는다.\n괜찮다는 듯 손을 펴고, 천천히 몸짓을 되풀이한다.)',
  '(아빠가 작게 고개를 저으며 눈웃음을 짓는다.\n몸짓을 하나씩 다시 보여 준다.)',
  '(아빠가 내 손등을 토닥인다.\n천천히 하자는 듯 손바닥을 낮추고, 다시 해 보인다.)'];
function gesture(i){
  const g=GESTURES[i];dadPose(g.pose);
  talk([['아빠',g.act,g.opts.map(([t,ok])=>({t,go:()=>{
    if(!ok){dadPose('retry');talk([['아빠',RETRIES[Math.floor(Math.random()*RETRIES.length)]]],()=>gesture(i));return;}
    const next=()=>i+1<MG.dad_steps?gesture(i+1):dadLedger();
    dadPose(g.reply);Sound.yeongsan('dad');talk([['아빠',g.after]],next);
  }}))]]);
}
function dadLedger(){
  const F=G.f;F.dadDone=true;addItem('dad_ledger',1);learn('dad:ledger');
  clue('y2','아빠의 장부 한 장','엄마의 글씨: "제 둔갑과 말을 드립니다. 아이의 숨을 주세요." 그 아래 아빠의 글씨: "말 하나 더함."');
  diary('y_ledger','아빠가 내민 장부에 엄마의 글씨가 있었다. "제 둔갑과 말을 드립니다. 아이의 숨을 주세요." 그 아래에는 아빠의 글씨. "말 하나 더함." 엄마가 아픈 건 나를 살린 값이었다.');
  sceneNext('y_dad_ledger');
  talk([['너구리','(낡은 장부다. 이 글씨는…)'],
    ['너구리','(엄마의 글씨) "제 둔갑과 말을 드립니다. 아이의 숨을 주세요."'],
    ['너구리','(그 아래, 아빠의 글씨) "말 하나 더함."'],
    ['너구리','…나를 살리려고?'],
    ['아빠','(아빠가 내 손을 꼭 잡는다.\n신목 쪽에 드리운 커다란 그림자를 가리킨다.)']],()=>{Rg.dadPose=null;refreshGoal();});
}
function talkDad(){
  const F=G.f;
  // 아빠는 집안 사람이라 변신한 아이를 알아본다 (leaf-transform.md 6-4).
  if(G.form&&F.dadMet){talk([['아빠','(아빠가 보따리 끈의 잎사귀를 손가락으로 톡 친다.\n다 안다는 얼굴이다.)']]);return;}
  const c=dadArcChoices();
  if(c.length){talk([['아빠','(아빠가 나를 보고 고개를 든다.)',[...c,{t:'아빠 곁에 있는다',go:dadMain}]]]);return;}
  dadMain();
}
function dadMain(){
  const F=G.f;
  if(!F.dadMet){F.dadMet=true;
    sceneNext('y_dad_reunion');   // 결정 D-72: 알아보는 "…아빠?"부터 아빠 곡
    talk([['너구리','(호숫가의 너구리가 신목을 바라보고 있다. 저 뒷모습은…)'],['너구리','…아빠?'],
      ['아빠','(아빠가 돌아본다. 벌떡 일어나 나를 꽉 끌어안는다.\n입이 달싹이는데, 숨소리만 들린다.)']],()=>gesture(0));return;}
  if(!F.dadDone){gesture(0);return;}
  if(!F.nameGiven){talk([['아빠','(아빠가 신목 쪽을 가리키다 말고 내 손을 꼭 쥔다.\n한참 만에야 손을 놓고, 내 어깨를 두드린다.)']]);return;}
  if(F.yakDone){returnPrep();return;}
  talk([['아빠','(아빠가 보따리 속 약연을 가리키며 고개를 끄덕인다.)']]);
}

/* ---------- 영산 사연 (결정 D-120) ----------
   아빠는 말을 잃었다(확정). 아빠의 말은 몸짓으로만 쓴다. 글도 못 쓴다(D-01 규칙 3)라서 그림·손도장만 쓴다.
   ① 아빠: 겨울 막대 → 녹은 땅의 그림 → 수첩의 손도장
   ② 날쌘과 아빠: 아이가 둘 사이에서 말을 나르는 보부상이 된다 (날쌘의 고백 D-03 뒤)
   ③ 늙은 까치: 아빠 소식 부치기 → 엄마의 답 → 마지막 남쪽 길 (아래 길손 블록) */
function arcScene(flag,lines,record,after){
  if(!arcs()||G.f[flag])return;
  talk(lines,()=>{G.f[flag]=true;diary(flag,record);if(after)after();});
}
Rg.arcScene=arcScene;
// 옹달샘 표주박 그림: 박 두 덩이, 나무 마개, 엄마 매듭으로 묶은 끈
