// 봄이 오면 샘이 풀린다. 할미는 표주박을 매듭 임자한테 돌려주라며 아이에게 맡긴다.
function ongdalArcSpring(){
  arcScene('yOngdal4',[
    ['옹달 할미','(얼었던 샘에서 물소리가 난다.\n할미가 솥을 엎어 말리고 있다.)'],
    ['옹달 할미','샘이 풀렸구먼. 솥은 이제 쉬어도 되고.'],
    ['옹달 할미','(할미가 표주박에 첫 샘물을 받아 마개를 막는다.\n그리고 내 손에 쥐여 준다.)'],
    ['너구리','이건 할머니 거잖아요.'],
    ['옹달 할미','끈은 내 게 아니지. 매듭 임자한테 갖다줘.'],
    ['옹달 할미','그리고 그 양반 빚도 받아 와.\n물 한 바가지. 집에서 갚으라고 해.'],
    ['너구리','…네.'],
    ['옹달 할미','국물 한 그릇은 내가 빚졌구먼.\n다음에 와. 솥 다시 걸어 놓을 테니.']],
    '봄이 와 옹달샘이 풀렸다. 할미는 첫 샘물을 담은 표주박을 내게 맡겼다. 끈은 매듭 임자한테 돌려주고, 아빠의 물 한 바가지 빚은 집에서 갚게 하라고.',
    ()=>{if(!has('ongdal_gourd'))addItem('ongdal_gourd',1);learn('ongdal:gourd');});
}
function talkOngdal(){
  const F=G.f;
  if(G.form){talk([['옹달 할미','(할미가 코를 킁킁거린다.)\n…낯선 짐승이구먼. 물 마시고 가.']]);return;}
  if(!arcs()){talk([['옹달 할미','샘이 얼어서 눈을 녹이는 중이여.\n한 모금 하고 가.']]);learn('met:ongdal',true);return;}
  if(!F.yOngdal1){ongdalArcMeet();return;}
  if(!F.yOngdal2){talk([['옹달 할미','표주박은 비탈 고라니 몫이여.\n식기 전에 갖다줘.']]);return;}
  if(!F.yOngdalSoup){ongdalArcSoup();return;}
  if(!F.yOngdal3){
    if(F.dadDone){ongdalArcKnot();return;}
    talk([['옹달 할미','솥은 계속 걸어 둔다.\n목마르면 또 와.']]);return;
  }
  if(!F.yOngdal4){
    if(G.boss.dead){ongdalArcSpring();return;}
    talk([['옹달 할미','이무기가 호수를 놓아야 샘도 풀리지.\n솥은 그때까지 걸어 둬야고.']]);return;
  }
  if(F.yakDone&&!F.yOngdalBye){ongdalArcFarewell();return;}
  talk([['옹달 할미','표주박 잘 챙겨.\n매듭 임자 손에 쥐여 줘야 혀.']]);
}
// 떠나기 전: 할미가 빚진 국물 한 그릇. 샘이 풀려 솥은 쉬지만, 국물만은 다시 끓였다.
